import 'package:flutter/material.dart';
import '../../models/delivery_model.dart';
import 'executive_repository.dart';

class UpdateStatusScreen extends StatefulWidget { final DeliveryModel delivery; final ExecutiveRepository repository; const UpdateStatusScreen({super.key, required this.delivery, required this.repository}); @override State<UpdateStatusScreen> createState() => _UpdateStatusScreenState(); }
class _UpdateStatusScreenState extends State<UpdateStatusScreen> { bool _busy = false; String? _error; String get _next => widget.delivery.status == 'ASSIGNED' ? 'PICKED UP' : widget.delivery.status == 'PICKED UP' ? 'OUT FOR DELIVERY' : 'DELIVERED'; Future<void> _submit() async { if (!canMoveTo(widget.delivery.status, _next)) { setState(() => _error = 'This status transition is not allowed.'); return; } setState(() { _busy = true; _error = null; }); try { await widget.repository.updateStatus(widget.delivery, _next); if (mounted) { ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Status updated.'))); Navigator.pop(context); } } catch (e) { if (mounted) setState(() => _error = e.toString()); } finally { if (mounted) setState(() => _busy = false); } } @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Update status')), body: Padding(padding: const EdgeInsets.all(20), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Move from ${widget.delivery.status} to $_next?'), const SizedBox(height: 8), const Text('This action is saved to the delivery record.'), const Spacer(), if (_error != null) Text(_error!, style: TextStyle(color: Theme.of(context).colorScheme.error)), const SizedBox(height: 12), SizedBox(width: double.infinity, height: 52, child: FilledButton(onPressed: _busy ? null : _submit, child: _busy ? const CircularProgressIndicator() : const Text('Confirm update')))])); }